pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple mock that records the last transferFrom call
        MockReceiver mock = new MockReceiver();
        address[] memory tos = new address[](1);
        tos[0] = address(mock);
        // Call transfer with v=0, decimals=1, so reference: _value = 0 * 10**1 = 0, bug: _value = 0 + 10**1 = 10
        c.transfer(address(0xdead), address(mock), tos, 0, 1);
        // The reference transfers 0 tokens, the bug transfers 10 tokens.
        // MockReceiver's lastValue public getter shows the difference.
        assertTrue(mock.lastValue() == 10);
    }
}

contract MockReceiver {
    uint256 public lastValue;
    function transferFrom(address, address, uint256 value) external returns (bool) {
        lastValue = value;
        return true;
    }
    // Fallback to accept any call (though transferFrom is called via selector)
    fallback(bytes calldata) external returns (bytes memory) {
        // decode and call transferFrom
        (address from, address to, uint256 value) = abi.decode(msg.data[4:], (address, address, uint256));
        lastValue = value;
        return abi.encode(true);
    }
}

