pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple contract that reverts on any non-zero transfer
        address target = address(new Rejector());
        address[] memory tos = new address[](1);
        tos[0] = address(0x1111);
        // The call will be made to target; if _value != 0, Rejector.fallback reverts
        bool ok;
        try c.transfer(address(this), target, tos, 0, 0) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference returns true (ok=true); bug would revert (ok=false)
        assertTrue(ok, "Reference should succeed with v=0, decimals=0");
    }
}

contract Rejector {
    fallback() external payable {
        // Revert if any value sent (non-zero _value)
        if (msg.value > 0) revert();
    }
}
